198	\subsection{Sanity check in low genus}
199	\begin{itemize}
200	  \item \(g = 0\): Then \(\Jac(C) = \Spec k\), the trivial group scheme; \(\Jac(\mathbb P^1_k) = \Spec k\) is smooth of relative dimension \(0 = g\).
201	  \item \(g = 1\): Then \(\Jac(C) \cong C\) once a \(k\)-rational point on \(C\) is fixed; \(C\) is itself an elliptic curve (abelian variety of dimension \(1\)).
202	  \item \(g \ge 2\): \(\Jac(C)\) is a non-trivial \(g\)-dimensional abelian variety, never isomorphic to \(C\) as a scheme.
203	\end{itemize}
204	\section{Existence of an Albanese variety}
205	The classical construction of the Jacobian goes through the Picard scheme machinery: \(\Jac(C)\) is the connected component of the identity of \(\Pic^0_{C/k}\). An equivalent route, available whenever a \(k\)-rational point \(P \in C(k)\) has been fixed, is to take the Stein factorisation of the Abel--Jacobi morphism \(\Sym^g(C) \to \Pic^g_{C/k}\) and translate by \(-gP\).
206	\subsection{The Albanese witness bundle}
207	Before stating the existence theorem, we package its conclusion into a single structure --- the \emph{Albanese witness} of \(C\). This bundling reverses the quantifier order of the classical statement (see Remark~\ref{rem:JacobianWitness_quantifier_order}) and is the data structure consumed by the \texttt{Jacobian} family of declarations in this file and by the \texttt{AbelJacobi} interface of Chapter~\ref{chap:AbelJacobi}.
208	\begin{definition}
209	\leanok
210	  \uses{def:IsAlbanese, def:genus}
211	[Albanese witness for a curve]
212	  \label{def:JacobianWitness}
213	  
214	  \lean{AlgebraicGeometry.JacobianWitness}
215	  An \emph{Albanese witness} for the smooth proper geometrically irreducible curve \(C\) over \(k\) is a bundle of the following seven fields:
216	  \begin{itemize}
217	    \item \(J\): an object of the category of \(k\)-schemes over \(\Spec k\) --- the candidate Albanese object.
218	    \item \(\mathtt{grpObj}\): a group-object structure on \(J\) in the category of \(k\)-schemes over \(\Spec k\).
219	    \item \(\mathtt{proper}\): a proof that the structure morphism \(J \to \Spec k\) is proper.
220	    \item \(\mathtt{smooth}\): a proof that the structure morphism \(J \to \Spec k\) is smooth.
221	    \item \(\mathtt{geomIrred}\): a proof that the structure morphism \(J \to \Spec k\) is geometrically irreducible.
222	    \item \(\mathtt{smoothGenus}\): a proof that the structure morphism \(J \to \Spec k\) is smooth of relative dimension \(g(C)\). This refines \(\mathtt{smooth}\) at the specific relative dimension \(\genus\, C\) (see Remark~\ref{rem:JacobianWitness_smooth_redundancy}).
223	    \item \(\mathtt{isAlbaneseFor}\): a proof that, for every \(k\)-rational marked point \(P \in C(k)\), the scheme \(J\) together with its group-object, proper, smooth, and geometrically-irreducible structures satisfies the Albanese universal property for the pointed curve \((C, P)\) in the sense of Definition~\ref{def:IsAlbanese}.
224	  \end{itemize}
225	  Formally, an Albanese witness is a Lean-level record (a structure) whose name is \texttt{JacobianWitness}.
226	\end{definition}
227	\begin{remark}
228	  \label{rem:JacobianWitness_quantifier_order}
229	  The classical phrasing of the existence statement of an Albanese variety is
230	  \[
231	    \forall\, P \in C(k),\ \exists\, J,\ J \text{ is an Albanese object for } (C, P).
232	  \]
233	  The witness bundle reverses these quantifiers: a single \(J\) is chosen once (intrinsic to \(C\)), and the marked-point-dependent data is recorded as the family-valued field
234	  \[
235	    \mathtt{isAlbaneseFor} \colon \forall\, P \in C(k),\ \mathrm{IsAlbanese}\,C\,P\,J.
236	  \]
237	  Mathematically this reversal is justified because the underlying scheme of any Albanese object is intrinsic to \(C\): a different choice of \(P \in C(k)\) alters the universal morphism \(\iota_P \colon C \to J\) by a translation of \(J\), which is an automorphism of \(J\), and so leaves \(J\) unchanged as a scheme. The reversed bundling is what makes the per-\(P\) projection in Chapter~\ref{chap:AbelJacobi} clean: \(\mathtt{Jacobian.ofCurve}\), \(\mathtt{Jacobian.comp\_ofCurve}\), and \(\mathtt{Jacobian.exists\_unique\_ofCurve\_comp}\) each take a marked point \(P\) as input and project the corresponding component of \(\mathtt{isAlbaneseFor}\,P\) via the extraction trio (Definition~\ref{def:IsAlbanese_ofCurve}, Lemmas~\ref{lem:IsAlbanese_comp_ofCurve}, \ref{lem:IsAlbanese_exists_unique_ofCurve_comp}).
238	\end{remark}
239	\begin{remark}
240	  \label{rem:JacobianWitness_smooth_redundancy}
241	  The fields \(\mathtt{smooth}\) and \(\mathtt{smoothGenus}\) of an Albanese witness are mathematically redundant: the relative-dimension version implies the unqualified version via Mathlib's \texttt{AlgebraicGeometry.SmoothOfRelativeDimension.smooth}. Keeping both fields is a Lean-level convenience: \(\mathtt{smooth}\) is the form required by the typeclass binder of \texttt{IsAlbanese} (and by the protected \(\mathtt{Jacobian.instGrpObj}\) projection), whereas \(\mathtt{smoothGenus}\) is the form required by the protected \(\mathtt{Jacobian.smoothOfRelativeDimension\_genus}\) projection. The redundancy carries no mathematical cost (the two fields agree) and no soundness cost (deriving one from the other would only re-run the same Mathlib instance synthesis at the projection sites).
242	  \uses{def:IsAlbanese, def:genus, def:JacobianWitness}
243	\end{remark}
